def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))
    wall = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]

    # The diagonal strokes pair off as an outer pair and a lower pair.
    # Fill the spaces between each paired set, preserving the original strokes.
    for r, row in enumerate(grid):
        walls = [c for c, v in enumerate(row) if v == wall]
        pairs = []
        if len(walls) >= 2:
            pairs.append((walls[0], walls[1]))
        if len(walls) >= 4:
            pairs.append((walls[2], walls[3]))
        for left, right in pairs:
            for c in range(left + 1, right):
                if out[r][c] == bg:
                    out[r][c] = 2
    return out
